<?php
require_once __DIR__.'/includes/functions.php';require_login();$s=$pdo->prepare("SELECT r.*,s.name subject_name,s.code subject_code FROM bookmarks b JOIN resources r ON r.id=b.resource_id LEFT JOIN subjects s ON s.id=r.subject_id WHERE b.user_id=? AND r.status='approved' ORDER BY b.created_at DESC");$s->execute([current_user()['id']]);$rows=$s->fetchAll();$page_title='My bookmarks';require __DIR__.'/includes/header.php';?>
<section class="page-heading"><span class="eyebrow">YOUR READING LIST</span><h1>Saved resources</h1><p>Resources you've bookmarked for later.</p></section><div class="resource-grid"><?php foreach($rows as $r): ?><article class="resource-card"><div class="file-thumb">PDF</div><div class="resource-info"><span class="pill"><?= e(str_replace('_',' ',$r['type'])) ?></span><h3><?= e($r['title']) ?></h3><p><?= e($r['subject_code']??'') ?> <?= e($r['subject_name']??'') ?></p><a class="card-link" href="<?= url('resource.php?id='.$r['id']) ?>">Open resource →</a></div></article><?php endforeach; if(!$rows): ?><div class="empty">No bookmarks yet. Save useful resources from their detail pages.</div><?php endif; ?></div><?php require __DIR__.'/includes/footer.php';?>